import type {
  ConversationId, UserId, MessageId, ClientMsgId, AttachmentId, Seq,
} from '../ids.js';
import type { CipherEnvelope } from './crypto.js';
import type { MessageKind } from './conversation.js';

/**
 * System events are generated by the server, so they cannot be E2EE and are
 * not pretending to be. They carry a code plus actor ids — all of which the
 * server already knows because it performed the action.
 */
export interface SystemEvent {
  code:
    | 'member_added'
    | 'member_removed'
    | 'member_left'
    | 'conversation_created'
    | 'call_started'
    | 'call_ended'
    | 'rekeyed';
  actorId: UserId;
  targetId?: UserId;
}

export interface MessageDTO {
  id: MessageId;
  conversationId: ConversationId;
  seq: Seq;
  senderId: UserId;
  clientMsgId: ClientMsgId;
  kind: MessageKind;
  /** Ciphertext. Absent for system messages and for tombstoned messages. */
  envelope?: CipherEnvelope;
  system?: SystemEvent;
  /**
   * Server-visible pointer. The filename, MIME type and per-file key all live
   * INSIDE the envelope plaintext, because "Q3_layoffs.xlsx" leaks plenty.
   */
  attachmentId?: AttachmentId;
  replyToId?: MessageId;
  /**
   * Client clock, authenticated via AAD. DISPLAY THIS.
   * `createdAt` is server-assigned after signing so it cannot be in the AAD,
   * which means it is unauthenticated metadata and must not drive the UI.
   */
  sentAt: number;
  createdAt: number;
  deletedAt?: number;
}

/** The plaintext inside a `kind: 'file'` envelope. Never touches the server. */
export interface FilePayload {
  attachmentId: AttachmentId;
  filename: string;
  mime: string;
  plainSize: number;
  chunkCount: number;
  /** 4-byte IV prefix; the chunk counter fills the remaining 8. */
  ivPrefix: string;
  /** SHA-256 of the plaintext, for post-decrypt integrity display. */
  sha256: string;
  /** The per-file AES-256-GCM key, raw, base64url. Sealed with the message. */
  fileKey: string;
  /** Optional caption typed alongside the attachment. */
  caption?: string;
}
